from mk import *
from lib import fbd
STRICT["on"] = True

def fig():
    g = Fig(560, 300, "תרשים 1: תיבה m נעה ימינה לעבר תיבה M במנוחה. תרשים 2: גרף המהירות של שתי התיבות כפונקציה של הזמן באלפיות שנייה: m יורדת מ-2 ל-1.2- בין 1 ל-3 אלפיות שנייה, ו-M עולה מאפס ל-0.8")
    X, Y = g.graph(70, 220, 360, 190, "t (ms)", "v (m/s)", xticks=[(t, f"{t:g}") for t in (0.5, 1, 1.5, 2, 2.5, 3, 3.5)], yticks=[(v, f"{v:g}") for v in (-1.5, -1, -0.5, 0.5, 1, 1.5, 2, 2.5)], xmax=3.6, ymin=-1.6, ymax=2.6)
    g.plot(X, Y, [(0, 2), (1.05, 2), (2.95, -1.2), (3.5, -1.2)])
    g.plot(X, Y, [(0, 0), (0.95, 0), (2.9, 0.8), (3.5, 0.8)], stroke="var(--d-line)")
    g.text(X(3.45), Y(0.8) - 8, "M"); g.text(X(3.45), Y(-1.2) + 18, "m")
    g.ground(450, 550, 60, depth=6); g.block(470, 46, 20, 20, "m"); g.arrow(484, 40, 506, 40, None); g.block(530, 46, 24, 24, "M")
    return g

E(id="bagrut-2016-q4", year=2016, label="2016 שאלה 4", topic="momentum", sub="mom-collisions", diff=3, fig=fig,
  stem=r"תיבה שמסתה $m = 0.5\,\text{kg}$ נעה על משטח אופקי חלק אל תיבה שמסתה $M$, שעומדת במקום. התיבות מתנגשות התנגשות אלסטית. הגרף מראה את המהירויות של שתי התיבות כפונקציה של הזמן. שימו לב: הזמן בגרף באלפיות שנייה. ענו על הסעיפים לפי הגרף.",
  parts=[
    P("א", r"תארו במילים איך נעה התיבה $m$ בזמן שמתואר בגרף.", OPEN, ["graph"], [
        X(r"הכיוון החיובי הוא כיוון התנועה ההתחלתי של התיבה הקטנה."),
        S(r"השלבים", r"קודם המהירות קבועה. בזמן ההתנגשות המהירות קטנה עד אפס, מתהפכת וגדלה בכיוון ההפוך. אחרי ההתנגשות היא שוב קבועה", r"2 \to 0 \to -1.2\,\text{m/s}"),
    ], r"מהירות קבועה, האטה עד עצירה, תאוצה בכיוון ההפוך, ושוב מהירות קבועה בכיוון ההפוך"),
    P("ב", r"מה המסה של התיבה $M$?", num(2, "kg"), ["graph", "principle"], [
        S(r"שימור תנע", r"קוראים את המהירויות מהגרף, לפני ההתנגשות ואחריה", r"0.5 \cdot 2 + M \cdot 0 = 0.5\,(-1.2) + M \cdot 0.8", eq=r"m_A\vec v_A + m_B\vec v_B = m_A\vec u_A + m_B\vec u_B"),
        S(r"פותרים", r"מבודדים את המסה", r"M = \frac{1 + 0.6}{0.8} = 2\,\text{kg}"),
    ], r"$2\,\text{kg}$", key=r"M=2 kg"),
    P("ג", r"מה הכוח השקול הממוצע שפעל על התיבה $M$ בזמן ההתנגשות?", num(800, "N", tol=5), ["graph", "principle", "units"], [
        S(r"שינוי התנע של התיבה", r"התיבה התחילה ממנוחה", r"\Delta p = 2 \cdot 0.8 - 0 = 1.6\,\text{kg}\cdot\text{m/s}", eq=r"\vec p = m\vec v"),
        S(r"משך ההתנגשות", r"מהגרף, מאלפית שנייה אחת עד שלוש", r"\Delta t = 2 \cdot 10^{-3}\,\text{s}"),
        S(r"הכוח הממוצע", r"המתקף שווה לשינוי התנע, והמתקף הוא הכוח הממוצע כפול הזמן", r"\bar F \cdot 0.002 = 1.6 \;\Rightarrow\; \bar F = 800\,\text{N}", eq=r"\vec J_{\text{tot}} = \Delta\vec p"),
    ], r"$800\,\text{N}$, בכיוון התנועה ההתחלתי", key=r"800 N ימינה"),
    P("ד", r"בגרף רואים שבזמן ההתנגשות השיפועים של שתי העקומות שונים בגודל ובסימן. הסבירו את ההבדל בעזרת חוקי ניוטון.", OPEN, ["principle"], [
        S(r"השיפוע הוא התאוצה", r"בגרף מהירות-זמן השיפוע הוא התאוצה, ולפי החוק השני התאוצה היא הכוח חלקי המסה", r"a = \frac{F}{m}", eq=r"\Sigma\vec F = m\vec a"),
        S(r"הסימן", r"לפי החוק השלישי הכוחות שהתיבות מפעילות זו על זו הפוכים בכיוון, ולכן התאוצות בסימנים הפוכים", r"\vec F_{m,M} = -\vec F_{M,m}", eq=r"\vec F_{1,2} = -\vec F_{2,1}"),
        S(r"הגודל", r"הכוחות שווים בגודלם, אבל המסות שונות. לתיבה הקלה תאוצה גדולה יותר", r"\frac{|a_m|}{|a_M|} = \frac{M}{m} = \frac{2}{0.5} = 4"),
    ], r"הכוחות שווים והפוכים, ולכן הסימנים הפוכים. המסות שונות, ולכן הגדלים שונים"),
    P("ה", r"הוכיחו שההתנגשות אלסטית.", OPEN, ["principle", "algebra"], [
        S(r"האנרגיה לפני", r"רק התיבה הקטנה נעה", r"E_k = \tfrac{1}{2} \cdot 0.5 \cdot 2^2 = 1\,\text{J}", eq=r"E_k = \tfrac{1}{2}mv^2"),
        S(r"האנרגיה אחרי", r"שתי התיבות נעות", r"E_k' = \tfrac{1}{2} \cdot 0.5 \cdot 1.2^2 + \tfrac{1}{2} \cdot 2 \cdot 0.8^2 = 0.36 + 0.64 = 1\,\text{J}"),
    ], r"האנרגיה הקינטית נשמרה: $1\,\text{J}$ לפני ואחרי"),
    P("ו", r"מחליפים את התיבה $M$ בתיבה אחרת שמסתה $M'$, וההתנגשות שוב אלסטית. מה המסה המרבית של $M'$, כך שהתיבה $m$ לא תשנה את כיוון התנועה שלה אחרי ההתנגשות?", num(0.5, "kg"), ["principle", "algebra"], [
        S(r"שימור תנע", r"התיבה השנייה עומדת לפני ההתנגשות", r"m v = m u + M' u'", eq=r"m_A\vec v_A + m_B\vec v_B = m_A\vec u_A + m_B\vec u_B"),
        S(r"התנגשות אלסטית", r"מהירות ההתקרבות שווה למהירות ההתרחקות", r"v - 0 = -(u - u') \;\Rightarrow\; u' = u + v", eq=r"v_A - v_B = -(u_A - u_B)"),
        S(r"מהירות התיבה הקטנה אחרי", r"מציבים בשימור התנע ומבודדים", r"m v = m u + M'(u + v) \;\Rightarrow\; u = \frac{m - M'}{m + M'}\,v"),
        S(r"התנאי", r"התיבה לא משנה כיוון אם המהירות שלה אחרי לא שלילית", r"u \ge 0 \;\Rightarrow\; M' \le m = 0.5\,\text{kg}"),
    ], r"$0.5\,\text{kg}$", key=r"M'=0.5 kg"),
  ],
  concepts=["התנגשות אלסטית", "שימור תנע", "כוח ממוצע", "החוק השלישי של ניוטון", "גרף מהירות-זמן"],
  summary=r"מגרף מהירויות בהתנגשות: המסה של התיבה השנייה, הכוח הממוצע, הוכחה שההתנגשות אלסטית, ומתי התיבה הפוגעת לא חוזרת.",
  review="הנחה שלי.\nמה לבדוק: רק לאשר.")
